import { format } from 'prettier';
import { describe, expect, test } from 'vitest';
import {
  defineFields,
  list,
  number,
  schemaFileMatches,
  text,
  toSchemaFile,
} from '@edity/core';

const label = text({ maxChars: 24 });

describe('toSchemaFile', () => {
  test('writes the JSON Schema with its keys in sorted order, two-space indented and ending in a newline', () => {
    const home = defineFields({
      title: text({ maxChars: 20 }),
      price: number({ min: 0, max: 500, decimals: 0 }),
    });

    expect(toSchemaFile(home)).toBe(
      String.raw`{
  "$comment": "Generated by Edity from this page's Field definitions. Do not edit.",
  "$schema": "https://github.com/RMYPG/edity/contracts/v1/schema",
  "additionalProperties": false,
  "properties": {
    "price": {
      "maximum": 500,
      "minimum": 0,
      "type": "integer"
    },
    "title": {
      "pattern": "^[\\t\\v\\f\\p{Zs}]*[^\\t\\v\\f\\p{Zs}\\n\\r\\p{Zl}\\p{Zp}][^\\n\\r\\p{Zl}\\p{Zp}]*$",
      "type": "string",
      "x-edity-maxGraphemes": 20
    }
  },
  "required": ["title", "price"],
  "type": "object"
}
`,
    );
  });

  test("passes a Site's `prettier --check`, so the file needs no .prettierignore entry", async () => {
    // Long enough for the top-level "required" not to fit in 80 columns.
    const home = defineFields({
      hero: { title: text({ maxChars: 40, maxLines: 2 }), cta: label },
      plans: list(
        {
          name: text({ maxChars: 30 }),
          price: number({ min: 0, max: 999.99, decimals: 2 }),
          features: list(text({ maxChars: 60 }), { min: 0, max: 4 }),
        },
        { min: 1, max: 3 },
      ),
      testimonials: list(text({ maxChars: 200 }), { min: 0, max: 6 }),
      contactEmailLabel: label,
      openingHoursLabel: label,
    });
    const file = toSchemaFile(home);

    expect(file).toContain('"required": [\n    "hero",');
    expect(file).toContain('"required": ["name", "price", "features"]');
    await expect(format(file, { parser: 'json' })).resolves.toBe(file);
  });

  test.each([
    { columns: 80, oneLine: true },
    { columns: 81, oneLine: false },
  ])(
    'agrees with Prettier on a list of Field names $columns columns wide',
    async ({ columns, oneLine }) => {
      // `  "required": ["xx…x", "b"],` is 24 columns plus the long name.
      const long = 'x'.repeat(columns - 24);
      const file = toSchemaFile(defineFields({ [long]: label, b: label }));

      expect(file.includes(`\n  "required": ["${long}", "b"],\n`)).toBe(
        oneLine,
      );
      await expect(format(file, { parser: 'json' })).resolves.toBe(file);
    },
  );

  test('gives the same bytes for the same Field definitions', () => {
    const build = () =>
      defineFields({
        hero: { title: text({ maxLines: 2, maxChars: 40 }) },
        bullets: list(text({ maxChars: 60 }), { max: 4, min: 1 }),
      });

    expect(toSchemaFile(build())).toBe(toSchemaFile(build()));
  });
});

describe('schemaFileMatches', () => {
  const fields = (maxChars: number) =>
    defineFields({
      hero: { title: text({ maxChars, maxLines: 2 }) },
      plans: list(
        { name: label, price: number({ min: 0, max: 500, decimals: 2 }) },
        { min: 1, max: 3 },
      ),
    });
  const committed = toSchemaFile(fields(20));

  test('matches the file written from the same Field definitions', () => {
    expect(schemaFileMatches(committed, fields(20))).toBe(true);
  });

  test('does not match once a Limit changes', () => {
    expect(schemaFileMatches(committed, fields(24))).toBe(false);
  });

  test('does not match once a Field is added', () => {
    const more = defineFields({
      hero: { title: text({ maxChars: 20, maxLines: 2 }), subtitle: label },
      plans: list(
        { name: label, price: number({ min: 0, max: 500, decimals: 2 }) },
        { min: 1, max: 3 },
      ),
    });

    expect(schemaFileMatches(committed, more)).toBe(false);
  });

  test.each([
    ['minified', JSON.stringify(JSON.parse(committed))],
    [
      'indented with four spaces',
      JSON.stringify(JSON.parse(committed), null, 4),
    ],
    ['with CRLF line endings', committed.replaceAll('\n', '\r\n')],
    [
      'with its keys in another order',
      JSON.stringify(
        Object.fromEntries(Object.entries(JSON.parse(committed)).reverse()),
      ),
    ],
  ])('still matches when only the formatting differs: %s', (_, file) => {
    expect(schemaFileMatches(file, fields(20))).toBe(true);
  });

  test.each([
    ['an empty file', ''],
    [
      'a merge conflict',
      `<<<<<<< HEAD\n${committed}=======\n${committed}>>>>>>> main\n`,
    ],
  ])('does not match a file that is not JSON: %s', (_, file) => {
    expect(schemaFileMatches(file, fields(20))).toBe(false);
  });
});
